SELECT p.gender, p.age, a.admit_provider_id, c.composite_risk_score, q.quartile, COUNT(DISTINCT CASE WHEN p.dod IS NOT NULL THEN a.hadm_id END) AS in_hospital_mortality_rate, COUNT(DISTINCT CASE WHEN c.cardiovascular_disease_risk_score IS NOT NULL THEN a.hadm_id END) AS cardiovascular_complication_rate, COUNT(DISTINCT CASE WHEN c.neurological_disease_risk_score IS NOT NULL THEN a.hadm_id END) AS neurological_complication_rate FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.hadm_id = d.hadm_id JOIN (SELECT hadm_id, composite_risk_score FROM composite_risk_scores) c ON a.hadm_id = c.hadm_id JOIN (SELECT hadm_id, quartile FROM quartiles) q ON a.hadm_id = q.hadm_id WHERE p.gender = 'F' AND p.age BETWEEN 85 AND 95 AND icd.long_title = 'Asthma exacerbation' GROUP BY p.gender, p.age, a.admit_provider_id, c.composite_risk_score, q.quartile ORDER BY q.quartile, in_hospital_mortality_rate, cardiovascular_complication_rate, neurological_complication_rate NULLS LAST;